--[=[
    @interface INZView
    视图接口定义
]=]
export type INZView = {

    --[=[
        数据上下文,用于存储和管理视图相关的数据
        @prop DataContext INZViewModel
    ]=]
    DataContext: INZViewModel,

    --[=[
        创建新的View实例
        @param viewScript Instance | table 视图脚本或表
        @param parent any 父级对象
        @return INZView
    ]=]
    new: (viewScript: any, parent: any) -> INZView,

    --[=[
        生命周期方法 - 加载时调用
    ]=]
    Load: (self: INZView) -> (),

    --[=[
        生命周期方法 - 启动时调用
    ]=]
    Start: (self: INZView) -> (),

    --[=[
        设置可连接属性
        @param symbol string 属性标识符
    ]=]
    SetConnectable: (self: INZView, symbol: string) -> any,

    --[=[
        设置可绑定属性
        @param symbol string 属性标识符
    ]=]
    SetBindable: (self: INZView, symbol: string) -> any,

    --[=[
        连接事件
        @param ... any 连接参数
        @return Connection
    ]=]
    Connect: (self: INZView, ...any) -> INZConnection,

    --[=[
        延迟连接事件
        @param ... any 连接参数
    ]=]
    LateConnect: (self: INZView, ...any) -> INZConnection,

    --[=[
        绑定命令
        @param cmdName string 命令名称
        @param ... any 绑定参数
        @return Connection
    ]=]
    Bind: (self: INZView, cmdName: string, ...any) -> INZConnection,

    --[=[
        命令后处理
        @param cmdName string 命令名称
        @param ... any 处理参数
        @return Connection
    ]=]
    After: (self: INZView, cmdName: string, ...any) -> INZConnection,

    --[=[
        解除绑定
        @param signalName any 信号名称或函数
    ]=]
    Unbind: (self: INZView, signalName: any) -> (),

    --[=[
        断开连接（Unbind的别名）
        @param signalName any 信号名称或函数
    ]=]
    Disconnect: (self: INZView, signalName: any) -> (),

    --[=[
        添加效果
        @param propertyPath string 属性路径
        @param func function 效果函数
    ]=]
    Effect: (self: INZView, propertyPath: string, func: (...any) -> any) -> (),

    --[=[
        使用数据上下文
        @param vmName string ViewModel名称
        @param func? function 回调函数
    ]=]
    UseDataContext: (self: INZView, vmName: string, func: ((context: any) -> ())?) -> (),

    --[=[
        结束使用数据上下文
    ]=]
    UsingEnd: (self: INZView) -> (),

    --[=[
        设置数据上下文
        @param vmName string ViewModel名称
    ]=]
    SetDataContext: (self: INZView, vmName: string) -> (),

    --[=[
        获取组件
        @param uiObj Instance UI对象
        @param component string 组件名称
        @return Component
    ]=]
    GetComponent: (self: INZView, uiObj: Instance, component: string) -> any,

    --[=[
        检查是否有组件
        @param uiObj Instance|string UI对象或组件名称
        @param component? string 组件名称
        @return boolean
    ]=]
    HasComponent: (self: INZView, uiObj: Instance | string, component: string?) -> boolean,

    --[=[
        设置禁用状态
        @param obj Instance 目标对象
    ]=]
    SetDisabled: (self: INZView, obj: Instance) -> (),

    --[=[
        获取节点
        @param objName string 节点名称
        @return Instance?
    ]=]
    GetNode: (self: INZView, objName: string) -> Instance?,

    --[=[
        放置节点
        @param obj Instance 节点对象
    ]=]
    PutNode: (self: INZView, obj: Instance) -> (),

    --[=[
        获取UI对象
        @param path string UI路径
        @param parent? Instance 父级对象
        @return Instance?
    ]=]
    GetUI: (self: INZView, path: string, parent: Instance?) -> Instance?,

    --[=[
        调整按钮悬停效果
        @param animationType string 动画类型
    ]=]
    AdjustButtonHover: (self: INZView, animationType: string) -> (),

    --[=[
        设置内容
        @param ui Instance UI实例
    ]=]
    SetContent: (self: INZView, ui: Instance) -> (),

    --[=[
        获取内容
        @return Instance?
    ]=]
    GetContent: (self: INZView) -> Instance?,

    --[=[
        启用Connect连接
    ]=]
    EnableConnect: (self: INZView) -> (),

    --[=[
        禁用Connect连接
    ]=]
    DisableConnect: (self: INZView) -> (),

    --[=[
        启用Bind绑定
    ]=]
    EnableBind: (self: INZView) -> (),

    --[=[
        禁用Bind绑定
    ]=]
    DisableBind: (self: INZView) -> (),

    --[=[
        启用After后处理
    ]=]
    EnableAfter: (self: INZView) -> (),

    --[=[
        禁用After后处理
    ]=]
    DisableAfter: (self: INZView) -> (),

    --[=[
        启用所有连接（Connect、Bind、After）
    ]=]
    Enable: (self: INZView) -> (),

    --[=[
        禁用所有连接（Connect、Bind、After）
    ]=]
    Disable: (self: INZView) -> ()
}

return {} 